"""Product-level delta: committed 08-29 clean/ CSVs (git HEAD) vs regenerated 09-15 clean/.

Compared on (unit, product) pairs, never on response_id - the synced workbook
renumbers responses.
"""
import csv
import io
import subprocess


def head_csv(name):
    out = subprocess.run(["git", "show", "HEAD:clean/" + name],
                         capture_output=True, text=True, encoding="utf-8", check=True).stdout
    return list(csv.DictReader(io.StringIO(out)))


def now_csv(name):
    with open("clean/" + name, encoding="utf-8") as f:
        return list(csv.DictReader(f))


def real(rows):
    return [r for r in rows if r["category"] != "excluded"]


o_master, n_master = real(head_csv("tech_master.csv")), real(now_csv("tech_master.csv"))
o_long, n_long = real(head_csv("tech_inventory_long.csv")), real(now_csv("tech_inventory_long.csv"))
o_stop, n_stop = head_csv("stopped_using.csv"), now_csv("stopped_using.csv")
n_cov = now_csv("coverage.csv")


def headline(master, long):
    return dict(
        products=len(master),
        mentions=len(long),
        athlete=sum(r["athlete_data_likely"] == "Y" for r in master),
        single=sum(int(r["unit_count"]) == 1 for r in master),
        shared3=sum(int(r["unit_count"]) >= 3 for r in master),
    )


print("HEADLINE  08-29 -> 09-15")
ho, hn = headline(o_master, o_long), headline(n_master, n_long)
for k in ho:
    print("  {:<9} {:>4} -> {:>4}  ({:+d})".format(k, ho[k], hn[k], hn[k] - ho[k]))
if "unit_count_self_reported" in n_master[0]:
    bo_only = [r for r in n_master if r["unit_count_self_reported"] == "0"]
    print("  products named ONLY by the Business Office:", len(bo_only))

print("\nCOVERAGE status counts (09-15):")
tally = {}
for r in n_cov:
    tally[r["status"]] = tally.get(r["status"], 0) + 1
print("  ", tally)
for r in n_cov:
    if r["status"] in ("BUSINESS OFFICE ONLY", "NO RESPONSE", "OFF-LIST ANSWER"):
        print("  ", r["unit"], "->", r["status"])

o_names = {r["canonical"] for r in o_master}
o_by = {r["canonical"]: r for r in o_master}
print("\nNEW PRODUCTS (not in 08-29):", sum(r["canonical"] not in o_names for r in n_master))
for r in sorted((r for r in n_master if r["canonical"] not in o_names),
                key=lambda r: (r["category"], r["canonical"])):
    bo = r.get("business_office_only_units", "")
    print("  {:<34} {:<18} athlete={} units={} [{}]{}".format(
        r["canonical"], r["category"], r["athlete_data_likely"], r["unit_count"],
        r["units"], "  BO-only: " + bo if bo else ""))

print("\nEXISTING PRODUCTS WITH MORE UNITS:")
for r in sorted(n_master, key=lambda r: -int(r["unit_count"])):
    o = o_by.get(r["canonical"])
    if o and int(r["unit_count"]) != int(o["unit_count"]):
        added = sorted(set(r["units"].split("; ")) - set(o["units"].split("; ")))
        bo = set(r.get("business_office_only_units", "").split("; ")) - {""}
        print("  {:<28} {:>2} -> {:>2}  +{}".format(
            r["canonical"], int(o["unit_count"]), int(r["unit_count"]),
            ", ".join(u + (" (BO)" if u in bo else "") for u in added)))

n_names = {r["canonical"] for r in n_master}
print("\nPRODUCTS IN 08-29 BUT NOT 09-15:", sorted(o_names - n_names))
o_pairs = {(r["unit"], r["canonical"]) for r in o_long}
n_pairs = {(r["unit"], r["canonical"]) for r in n_long}
print("unit x product pairs dropped:", sorted(o_pairs - n_pairs))
print("unit x product pairs added:", len(n_pairs - o_pairs))

o_stop_pairs = {(r["unit"], r["canonical"]) for r in o_stop}
print("\nRETIREMENTS  08-29: {}  09-15: {}".format(len(o_stop), len(n_stop)))
for r in n_stop:
    if (r["unit"], r["canonical"]) not in o_stop_pairs:
        print("  new:", r["unit"], "-", r["canonical"], "(", r["category"], ")")

print("\nPLANNED / COMING ONLINE (09-15):")
for r in n_long:
    if r["status"] == "planned":
        print("  ", r["unit"], "-", r["canonical"], "| raw:", r["raw_item"])

print("\nTOP SHARED (>=3 units) 09-15:")
for r in n_master:
    if int(r["unit_count"]) >= 3:
        print("  {:<24} {:>2} (self-reported {})".format(
            r["canonical"], int(r["unit_count"]), r.get("unit_count_self_reported", "?")))

